class Refused(Exception):
    def __init__(self, code):
        self.code = code
        super().__init__()


def require(condition, code):
    if not condition:
        raise Refused(code)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("ascii")


def host_guard():
    require(os.name == "posix", "DATAX01_ROOT_REQUIRED")
    require(os.geteuid() == 0 and os.uname().nodename.split(".")[0] == "datax-01", "DATAX01_ROOT_REQUIRED")


def identity(obj):
    return {"uid": obj["metadata"]["uid"], "generation": obj["metadata"].get("generation"), "spec_sha256": sha(canonical(obj["spec"]))}


def converged(deployment):
    spec, status = deployment["spec"], deployment.get("status", {})
    wanted = spec.get("replicas", 1)
    return bool(
        type(wanted) is int and wanted > 0 and not deployment["metadata"].get("deletionTimestamp")
        and not spec.get("paused", False)
        and status.get("observedGeneration") == deployment["metadata"]["generation"]
        and all(status.get(name, 0) == wanted for name in ("replicas", "updatedReplicas", "readyReplicas", "availableReplicas"))
        and status.get("terminatingReplicas", 0) == 0
    )


def controller(obj, kind, uid):
    owners = [r for r in obj["metadata"].get("ownerReferences", []) if r.get("controller") is True]
    return len(owners) == 1 and owners[0].get("kind") == kind and owners[0].get("uid") == uid


def ready_pod(pod, container):
    if pod["metadata"].get("deletionTimestamp") or pod.get("status", {}).get("phase") != "Running":
        return False
    if not any(c.get("type") == "Ready" and c.get("status") == "True" for c in pod.get("status", {}).get("conditions", [])):
        return False
    states = [s for s in pod.get("status", {}).get("containerStatuses", []) if s.get("name") == container]
    return len(states) == 1 and states[0].get("ready") is True and bool(states[0].get("state", {}).get("running"))


def owned_ready_pods(pods, replicasets, deployment, container):
    owners = {r["metadata"]["uid"]: r["metadata"]["name"] for r in replicasets if controller(r, "Deployment", deployment["metadata"]["uid"])}
    result = []
    for pod in pods:
        refs = [r for r in pod["metadata"].get("ownerReferences", []) if r.get("controller") is True]
        if len(refs) != 1 or refs[0].get("kind") != "ReplicaSet":
            continue
        ref = refs[0]
        if owners.get(ref.get("uid")) != ref.get("name") or not ready_pod(pod, container):
            continue
        declared = [c for c in pod["spec"].get("containers", []) if c.get("name") == container]
        expected = [c for c in deployment["spec"]["template"]["spec"]["containers"] if c.get("name") == container]
        if len(declared) == len(expected) == 1 and declared[0].get("image") == expected[0].get("image"):
            result.append(pod)
    return sorted(result, key=lambda p: p["metadata"]["name"])


def mounted_skill(pod, container):
    volumes = {v["name"] for v in pod["spec"].get("volumes", []) if v.get("persistentVolumeClaim", {}).get("claimName") == PVC}
    containers = [c for c in pod["spec"]["containers"] if c["name"] == container]
    require(len(containers) == 1, "CONSUMER_CONTAINER_SHAPE")
    roots = []
    target = PurePosixPath("public/energy-market-daily")
    for mount in containers[0].get("volumeMounts", []):
        if mount.get("name") not in volumes or "subPathExpr" in mount:
            continue
        sub = PurePosixPath(mount.get("subPath", ""))
        base = PurePosixPath(mount.get("mountPath", ""))
        require(base.is_absolute() and ".." not in sub.parts and not sub.is_absolute(), "SKILL_MOUNT_PATH")
        try:
            relative = target.relative_to(sub)
        except ValueError:
            continue
        roots.append(str(base / relative))
    require(len(roots) == 1, "ONE_REAL_SKILL_MOUNT_REQUIRED")
    return roots[0]


def runtime_identity(pod, container):
    require(ready_pod(pod, container), "CONSUMER_POD_NOT_READY")
    state = next(s for s in pod["status"]["containerStatuses"] if s["name"] == container)
    return dict(identity(pod), node=pod["spec"]["nodeName"], image_id=state.get("imageID"),
                container_id_sha256=sha(str(state.get("containerID", "")).encode()),
                restart_count=state.get("restartCount"), running_since=state["state"]["running"].get("startedAt"))


def maintenance_manifest(name, operation):
    return {
        "apiVersion": "v1", "kind": "Pod",
        "metadata": {"name": name, "namespace": NS, "labels": {"energy-market/chatfix-maintenance": operation}},
        "spec": {
            "restartPolicy": "Never", "automountServiceAccountToken": False,
            "activeDeadlineSeconds": 1200,
            "nodeSelector": {"kubernetes.io/hostname": NODE},
            "containers": [{
                "name": "maintenance", "image": IMAGE, "imagePullPolicy": "Never",
                "command": ["python3"], "args": ["-I", "-B", "-c", "import time;time.sleep(1200)"],
                "env": [{"name": "HOME", "value": "/tmp"}, {"name": "PYTHONUTF8", "value": "1"}],
                "resources": {"requests": {"cpu": "100m", "memory": "128Mi"}, "limits": {"cpu": "2", "memory": "2Gi"}},
                "securityContext": {"runAsUser": 0, "readOnlyRootFilesystem": True, "allowPrivilegeEscalation": False, "capabilities": {"drop": ["ALL"]}},
                "volumeMounts": [{"name": "skills", "mountPath": "/mnt/skills"}, {"name": "tmp", "mountPath": "/tmp"}],
            }],
            "volumes": [{"name": "skills", "persistentVolumeClaim": {"claimName": PVC}}, {"name": "tmp", "emptyDir": {"sizeLimit": "512Mi"}}],
        },
    }


def load_sealed():
    require(all(value != "UNSEALED" for value in (CHILD_B64, CHILD_SHA256, PAYLOAD_B64, PAYLOAD_SHA256)), "UNSEALED_TOOL")
    child = base64.b64decode(CHILD_B64, validate=True)
    payload = base64.b64decode(PAYLOAD_B64, validate=True)
    require(len(child) <= 262144 and len(payload) <= 262144, "SEALED_INPUT_BOUND")
    require(sha(child) == CHILD_SHA256 and sha(payload) == PAYLOAD_SHA256, "SEALED_INPUT_CHANGED")
    data = json.loads(payload)
    require(set(data) == {"files", "sha256"} and set(data["files"]) == set(FILES) and set(data["sha256"]) == set(FILES), "TWO_FILE_PAYLOAD_REQUIRED")
    for name in FILES:
        raw = base64.b64decode(data["files"][name], validate=True)
        require(sha(raw) == data["sha256"][name] and len(raw) <= 131072, "CANDIDATE_FILE_CHANGED")
    return child.decode("utf-8"), payload, data["sha256"]


class Update:
    def __init__(self):
        self.operation = uuid.uuid4().hex
        self.maintenance = "energy-chatfix-maint-" + self.operation[:12]
        self.pod_uid = None
        self.maintenance_identity = None
        self.commands = 0
        self.exec_targets = set()
        self.report = {
            "schema": "energy-market-chat-workflow-update.v1", "status": "INCOMPLETE", "operation": self.operation,
            "once_claimed": False, "automatic_retry": False, "automatic_rollback": False,
            "existing_deployment_mutations": 0, "secret_api_reads": 0, "credentials_read": False,
            "credentials_exported": False, "provider_requests": 0, "work_messages_sent": 0,
            "schedule_created": False, "business_acceptance_pending": True,
            "skill_publish_requested": False, "skill_switch_may_have_applied": False,
            "maintenance_create_requested": False, "maintenance_delete_requested": False,
            "maintenance_pod_absent": False, "raw_errors_exported": False,
        }

    def save(self):
        if not self.report["once_claimed"]:
            return
        require(not REPORT_DIR.is_symlink(), "REPORT_DIRECTORY_CHANGED")
        self.report["commands"] = self.commands
        temp = REPORT_DIR / ("REPORT-" + uuid.uuid4().hex + ".tmp")
        descriptor = os.open(str(temp), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(canonical(self.report))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(str(temp), str(REPORT_DIR / "REPORT.json"))

    def phase(self, name):
        self.report["last_step"] = name
        self.save()
        print(json.dumps({"phase": name}), flush=True)

    def validate_command(self, args, data):
        require(bool(args), "COMMAND_SCOPE")
        if args[0] == "get":
            require(len(args) > 1 and args[1] in ("deployments", "deployment", "node", "pvc", "pods", "pod", "replicasets"), "READ_SCOPE")
        elif args[0] == "create":
            obj = json.loads(data)
            require(args == ["create", "-f", "-", "-o", "json"] and obj == maintenance_manifest(self.maintenance, self.operation), "CREATE_SCOPE")
        elif args[0] == "delete":
            expected = ["delete", "--raw", "/api/v1/namespaces/" + NS + "/pods/" + self.maintenance, "-f", "-"]
            require(args == expected and isinstance(data, bytes), "DELETE_SCOPE")
            body = json.loads(data)
            require(args == expected and self.pod_uid and body == {
                "apiVersion": "v1", "kind": "DeleteOptions", "preconditions": {"uid": self.pod_uid}, "gracePeriodSeconds": 10,
            }, "DELETE_SCOPE")
        elif args[0] == "exec":
            require(len(args) > 7 and args[1] == "-i" and args[3] == "-c" and (args[2], args[4]) in self.exec_targets
                    and args[5:10] == ["--", "python3", "-I", "-B", "-c"], "EXEC_SCOPE")
        else:
            raise Refused("COMMAND_SCOPE")

    def command(self, args, data=None, timeout=30, bound=2097152, allow_child_failure=False):
        self.validate_command(args, data)
        self.commands += 1
        require(self.commands <= MAX_COMMANDS, "COMMAND_BUDGET")
        require(data is None or isinstance(data, bytes) and len(data) <= 1048576, "STDIN_BOUND")
        prefix = list(KUBE)
        if args[0] == "exec":
            prefix[2] = "--request-timeout=" + str(timeout) + "s"
        with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
            process = subprocess.Popen(prefix + args, stdin=subprocess.PIPE if data is not None else subprocess.DEVNULL,
                                       stdout=stdout, stderr=stderr, start_new_session=os.name == "posix")
            deadline = time.monotonic() + timeout
            pending = data
            try:
                while True:
                    require(os.fstat(stdout.fileno()).st_size <= bound and os.fstat(stderr.fileno()).st_size <= 262144, "COMMAND_OUTPUT_BOUND")
                    remaining = deadline - time.monotonic()
                    require(remaining > 0, "COMMAND_TIMEOUT")
                    try:
                        process.communicate(input=pending, timeout=min(0.2, remaining))
                        break
                    except subprocess.TimeoutExpired:
                        pending = None
                require(os.fstat(stdout.fileno()).st_size <= bound and os.fstat(stderr.fileno()).st_size <= 262144, "COMMAND_OUTPUT_BOUND")
                require(process.returncode == 0 or allow_child_failure and process.returncode == 1, "KUBECTL_COMMAND_FAILED")
                stdout.seek(0)
                return stdout.read(bound + 1)
            finally:
                if process.poll() is None:
                    if os.name == "posix":
                        os.killpg(process.pid, signal.SIGKILL)
                    else:
                        process.kill()
                    process.wait(timeout=10)

    def get(self, kind, name):
        return json.loads(self.command(["get", kind, name, "-o", "json"]))

    def snapshots(self):
        raw = self.command(["get", "deployments"] + list(PROTECTED) + ["-o", "json"])
        objects = {d["metadata"]["name"]: d for d in json.loads(raw)["items"]}
        require(set(objects) == set(PROTECTED), "PROTECTED_SET_CHANGED")
        for obj in objects.values():
            require(converged(obj), "PROTECTED_DEPLOYMENT_NOT_CONVERGED")
        collector = objects[COLLECTOR]
        require(identity(collector) == {"uid": COLLECTOR_UID, "generation": 2, "spec_sha256": COLLECTOR_SPEC}, "COLLECTOR_BASELINE_CHANGED")
        declared = {"spec": collector["spec"]["template"]["spec"]}
        require(mounted_skill(declared, "collector") == "/opt/energy-skill", "COLLECTOR_SUBPATH_CHANGED")
        return objects, {name: identity(obj) for name, obj in objects.items()}

    def infrastructure(self):
        node, pvc = self.get("node", NODE), self.get("pvc", PVC)
        require(node["metadata"]["uid"] == NODE_UID and not node["spec"].get("unschedulable")
                and any(c.get("type") == "Ready" and c.get("status") == "True" for c in node["status"].get("conditions", [])), "FIXED_NODE_NOT_READY")
        require(not any(t.get("effect") in ("NoExecute", "NoSchedule") for t in node["spec"].get("taints", [])), "FIXED_NODE_HARD_TAINT")
        require(pvc["metadata"]["uid"] == PVC_UID and pvc.get("status", {}).get("phase") == "Bound", "SKILLS_PVC_CHANGED")
        return {"node_uid": NODE_UID, "pvc": identity(pvc)}

    def inventory(self, deployment, container):
        selector = deployment["spec"]["selector"]
        require(not selector.get("matchExpressions") and bool(selector.get("matchLabels")), "SELECTOR_SHAPE")
        label = ",".join(k + "=" + v for k, v in sorted(selector["matchLabels"].items()))
        replicasets = json.loads(self.command(["get", "replicasets", "-l", label, "-o", "json"]))["items"]
        pods = json.loads(self.command(["get", "pods", "-l", label, "--field-selector=status.phase=Running", "-o", "json"], bound=16777216))["items"]
        return owned_ready_pods(pods, replicasets, deployment, container)

    def consumers(self, objects):
        by_node = {}
        for pod in self.inventory(objects["gateway"], "gateway"):
            by_node.setdefault(pod["spec"]["nodeName"], pod)
        require(len(by_node) >= 5, "FIVE_GATEWAY_NODES_REQUIRED")
        gateways = [by_node[name] for name in sorted(by_node)[:5]]
        collectors = self.inventory(objects[COLLECTOR], "collector")
        require(len(collectors) == 1, "ONE_CURRENT_COLLECTOR_POD_REQUIRED")
        return [(p, "gateway") for p in gateways] + [(collectors[0], "collector")]

    def claim(self):
        require(not any(p.is_symlink() for p in [REPORT_DIR] + list(REPORT_DIR.parents)), "REPORT_PATH_SYMLINK")
        require(not REPORT_DIR.exists(), "PRIOR_OPERATION_REVIEW_REQUIRED")
        REPORT_DIR.mkdir(mode=0o700)
        self.report.update(once_claimed=True, report_path=str(REPORT_DIR / "REPORT.json"), maintenance_pod=self.maintenance)
        self.save()

    def validate_maintenance(self, pod, require_ready=True):
        meta, spec = pod["metadata"], pod["spec"]
        expected = maintenance_manifest(self.maintenance, self.operation)["spec"]
        require(meta["name"] == self.maintenance and meta.get("labels", {}).get("energy-market/chatfix-maintenance") == self.operation
                and not meta.get("ownerReferences") and not meta.get("deletionTimestamp"), "MAINTENANCE_IDENTITY")
        if self.pod_uid is not None:
            require(meta["uid"] == self.pod_uid, "MAINTENANCE_UID_CHANGED")
        require(spec.get("automountServiceAccountToken") is False and spec.get("restartPolicy") == "Never"
                and spec.get("activeDeadlineSeconds") == 1200
                and spec.get("nodeName") in (None, NODE) and spec.get("nodeSelector") == expected["nodeSelector"]
                and not spec.get("initContainers") and not spec.get("ephemeralContainers")
                and not any(spec.get(k) for k in ("hostNetwork", "hostPID", "hostIPC")), "MAINTENANCE_SPEC_CHANGED")
        require(len(spec.get("containers", [])) == 1 and spec.get("volumes") == expected["volumes"], "MAINTENANCE_MOUNTS_CHANGED")
        current = spec["containers"][0]
        for key in ("name", "image", "imagePullPolicy", "command", "args", "env", "securityContext", "volumeMounts", "resources"):
            require(current.get(key) == expected["containers"][0][key], "MAINTENANCE_CONTAINER_CHANGED")
        require(not current.get("envFrom"), "MAINTENANCE_ENV_CHANGED")
        if require_ready:
            require(ready_pod(pod, "maintenance") and spec.get("nodeName") == NODE, "MAINTENANCE_NOT_READY")
            state = next(c for c in pod["status"]["containerStatuses"] if c["name"] == "maintenance")
            require(state.get("imageID") == IMAGE_ID and state.get("restartCount") == 0, "CACHED_IMAGE_IDENTITY_CHANGED")

    def create_maintenance(self):
        self.report["maintenance_create_requested"] = True
        self.save()
        self.command(["create", "-f", "-", "-o", "json"], canonical(maintenance_manifest(self.maintenance, self.operation)))
        for _ in range(35):
            pod = self.get("pod", self.maintenance)
            self.validate_maintenance(pod, require_ready=False)
            if self.pod_uid is None:
                self.pod_uid = pod["metadata"]["uid"]
                self.report["maintenance_pod_uid"] = self.pod_uid
                self.save()
            require(pod.get("status", {}).get("phase") not in ("Failed", "Succeeded"), "MAINTENANCE_EXITED")
            if ready_pod(pod, "maintenance"):
                self.validate_maintenance(pod)
                self.maintenance_identity = runtime_identity(pod, "maintenance")
                self.exec_targets.add((self.maintenance, "maintenance"))
                self.report["maintenance_runtime"] = self.maintenance_identity
                return
            time.sleep(2)
        raise Refused("MAINTENANCE_READY_TIMEOUT")

    def execute(self, pod, container, code, arguments=(), data=None, timeout=40):
        before = self.get("pod", pod["metadata"]["name"])
        require(runtime_identity(before, container) == runtime_identity(pod, container), "EXEC_RUNTIME_CHANGED")
        if container == "maintenance":
            self.validate_maintenance(before)
            require(runtime_identity(before, container) == self.maintenance_identity, "MAINTENANCE_RUNTIME_CHANGED")
        self.exec_targets.add((before["metadata"]["name"], container))
        raw = self.command(["exec", "-i", before["metadata"]["name"], "-c", container, "--", "python3", "-I", "-B", "-c", code] + list(arguments),
                           data=data, timeout=timeout, bound=32768, allow_child_failure=True)
        result = json.loads(raw)
        require(isinstance(result, dict), "CHILD_RESULT_SHAPE")
        after = self.get("pod", before["metadata"]["name"])
        require(runtime_identity(after, container) == runtime_identity(before, container), "EXEC_RUNTIME_CHANGED")
        return result

    def child(self, code, action, data):
        pod = self.get("pod", self.maintenance)
        return self.execute(pod, "maintenance", code, (action, self.operation), data, timeout=460 if action == "stage" else 150)

    def publish(self, before, infrastructure, code, stage, hashes):
        objects, current = self.snapshots()
        require(current == before and self.infrastructure() == infrastructure, "BASELINE_CHANGED_BEFORE_PUBLISH")
        selected = self.consumers(objects)
        require(self.snapshots()[1] == before, "BASELINE_CHANGED_BEFORE_PUBLISH")
        self.report["skill_publish_requested"] = True
        self.report["skill_switch_may_have_applied"] = True
        self.save()
        proof = canonical({"stage_manifest_sha256": stage["stage_manifest_sha256"], "sha256": hashes})
        publication = self.child(code, "publish", proof)
        self.report["publication"] = publication
        self.save()
        require(publication.get("status") == "TWO_FILE_UPDATE_ACCEPTED", "CHILD_PUBLISH_INCOMPLETE")
        verified = self.child(code, "verify", proof)
        self.report["publication_verification"] = verified
        self.save()
        require(verified.get("status") == "CHATFIX_LIVE_FILES_VERIFIED", "CHILD_VERIFY_INCOMPLETE")
        return selected

    def verify_consumers(self, selected, hashes):
        result = []
        expected = dict(SEALED_FILES, **hashes)
        self.report["consumers"] = result
        for pod, container in selected:
            path = mounted_skill(pod, container)
            row = {"pod": pod["metadata"]["name"], "uid": pod["metadata"]["uid"], "node": pod["spec"]["nodeName"], "container": container, "attempts": 0}
            result.append(row)
            for attempt in range(1, 6):
                # execute rechecks the same selected runtime identity before/after
                # every read. Only an already known NFS old/new view may wait.
                observation = self.execute(pod, container, OBSERVE, (path,))
                row.update(attempts=attempt, observation=observation)
                self.save()
                files = observation.get("files", {})
                require(observation.get("status") == "FIXED_SKILL_FILES_OBSERVED" and isinstance(files, dict)
                        and set(files) == set(expected), "CONSUMER_FILE_OBSERVATION_FAILED")
                require(all(files[name] == digest for name, digest in SEALED_FILES.items()), "CONSUMER_SEALED_FILES_CHANGED")
                require(all(files[name] in (OLD_FILES[name], hashes[name]) for name in FILES), "CONSUMER_UNKNOWN_WRAPPER_HASH")
                if files == expected:
                    break
                require(attempt < 5, "CONSUMER_FILES_NOT_PROPAGATED")
                time.sleep(2)
        self.save()

    def cleanup(self):
        pod = self.get("pod", self.maintenance)
        self.validate_maintenance(pod)
        self.report["maintenance_delete_requested"] = True
        self.save()
        options = {"apiVersion": "v1", "kind": "DeleteOptions", "preconditions": {"uid": self.pod_uid}, "gracePeriodSeconds": 10}
        self.command(["delete", "--raw", "/api/v1/namespaces/" + NS + "/pods/" + self.maintenance, "-f", "-"], canonical(options))
        self.report["maintenance_delete_acknowledged"] = True
        self.save()
        for _ in range(15):
            raw = self.command(["get", "pod", self.maintenance, "--ignore-not-found", "-o", "name"], bound=512)
            if not raw.strip():
                self.report["maintenance_pod_absent"] = True
                self.save()
                return
            time.sleep(2)
        raise Refused("MAINTENANCE_CLEANUP_PENDING")

    def run(self):
        host_guard()
        code, payload, hashes = load_sealed()
        self.phase("READ_CURRENT_BASELINE_AND_TWO_FILE_RELEASE")
        objects, before = self.snapshots()
        infrastructure = self.infrastructure()
        self.consumers(objects)
        require(self.snapshots()[1] == before, "BASELINE_CHANGED_DURING_PREFLIGHT")
        self.claim()
        self.report.update(before=before, infrastructure=infrastructure, candidate_sha256=hashes)
        self.phase("VERIFY_CACHED_RUNTIME_AND_STAGE_TWO_FILES")
        self.create_maintenance()
        staged = self.child(code, "stage", payload)
        self.report["staging"] = staged
        self.save()
        require(staged.get("status") == "STAGED_CHATFIX_ACCEPTED" and staged.get("candidate_sha256") == hashes
                and re.fullmatch(r"[0-9a-f]{64}", staged.get("stage_manifest_sha256", "")), "CHILD_STAGE_INCOMPLETE")
        self.phase("PUBLISH_ONLY_ENERGY_SKILL_OUTER_WORKFLOW")
        selected = self.publish(before, infrastructure, code, staged, hashes)
        self.phase("VERIFY_FIVE_GATEWAY_NODES_AND_COLLECTOR_MOUNT")
        self.verify_consumers(selected, hashes)
        require(self.snapshots()[1] == before and self.infrastructure() == infrastructure, "PROTECTED_BASELINE_CHANGED")
        self.report["after"] = before
        self.phase("CLEANUP_ONLY_OWNED_MAINTENANCE_POD")
        self.cleanup()
        self.report.update(status="ENERGY_CHAT_WORKFLOW_UPDATED_RUNTIME_ACCEPTED", skill_updated=True, last_step="complete")
        self.save()
        return self.report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--update-energy-market-chat-workflow-once", action="store_true", required=True)
    parser.parse_args()
    tool = Update()
    started = time.monotonic()
    try:
        tool.run()
    except Exception as exc:
        tool.report["error_code"] = exc.code if isinstance(exc, Refused) else "LOCAL_FAILURE_REDACTED"
        tool.report["error_class"] = "Refused" if isinstance(exc, Refused) else "LocalFailure"
    finally:
        tool.report["elapsed_seconds"] = round(time.monotonic() - started, 3)
        tool.report["observed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        tool.save()
    result = dict(tool.report)
    if tool.report["once_claimed"]:
        raw = (REPORT_DIR / "REPORT.json").read_bytes()
        result.update(report_bytes=len(raw), report_sha256=sha(raw))
    print(json.dumps(result, sort_keys=True))
    return 0 if result["status"] == "ENERGY_CHAT_WORKFLOW_UPDATED_RUNTIME_ACCEPTED" else 1


if __name__ == "__main__":
    sys.exit(main())
